/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Process Price Change tracking records for Trade agreements and create Price Data Feed records
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeTrack))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, TradeAgreement))]
public class METPriceChangeTrackTradeAgreement extends METPriceChangeTrack
{
}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <param name = "_showValidation">Show validation</param>
public void initInstance(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    this.setInternals(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <param name = "_showValidation">Show validation</param>
public void setInternals(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    super(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::TradeAgreement;
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void process()
    {
        priceDataFeedCount = 0;
        priceDataFeedList = this.createPriceDataFeedList();

        if(priceChangeTrackingOrig.PriceAttributeEnabled)
        {
            this.processAttr();
        }
        else
        {
            this.processStd();
        }

        if(priceDataFeedCount)
        {
            ttsbegin;
            priceDataFeedList.insertDatabase();
            ttscommit;
        }
    }

/// <summary>
/// Process the Change tracking record
/// </summary>
public void processStd()
{
    switch(priceChangeTrackingOrig.PriceDiscPartyCode)
    {
        case PriceDiscPartyCodeType::Table:
            this.processSingle();
            break;
        case PriceDiscPartyCodeType::GroupId:
            this.processGroup();
            break;
    }
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processAttr()
    {
        GUPPricingRuleCopy  pricingRuleCopyCustHeader, pricingRuleCopy;
        Query               custPreviewQuery;
        Query               productPreviewQuery;
        Set                 custAccountSet, inventItemSet;

        pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(priceChangeTrackingOrig.pricingRuleHeader));
        pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(priceChangeTrackingOrig.PricingRuleLine));

        custPreviewQuery = this.buildCustQueryBase(pricingRuleCopyCustHeader);
        custAccountSet = this.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);

        if(custAccountSet)
        {
            productPreviewQuery = this.buildProductQueryBase(pricingRuleCopy);
            inventItemSet = this.buildItemValues(productPreviewQuery, pricingRuleCopy);

            if(inventItemSet)
            {
                this.processSets(custAccountSet, inventItemSet);
            }
            else
            {
                if(showValidation)
                {
                    this.logMessage(strFmt('No products selected for processing\n'));
                }
            }
        }
        else
        {
            if(showValidation)
            {
                this.logMessage(strFmt('No customers selected for processing\n'));
            }
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processSingle()
    {
        boolean             validityCheck = true;
        
        //1. Execute the Item/Site validity check
        validityCheck = this.ItemSiteValidation(priceChangeTrackingOrig.ItemId, priceChangeTrackingOrig.InventSiteId);

        if(validityCheck)
        {
            //2. Execute the Customer/Item validity check
            validityCheck = this.CustomerItemValidation(priceChangeTrackingOrig.priceDiscAccountRelation, priceChangeTrackingOrig.ItemId);
        }

        if(validityCheck)
        {
            this.createPriceDataFeedAll(priceChangeTrackingOrig, priceChangeTrackingOrig.PriceDiscLineNum, METConstants::emptyString);
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processGroup()
    {
        CustTable           custTable;
        Set                 custAccountSet, inventItemSet;

        custAccountSet  = new Set(Types::String);
        inventItemSet   = new Set(Types::String);

        while select AccountNum
            from    custTable
            where   custTable.PriceGroup == priceChangeTrackingOrig.PriceDiscAccountRelation
        {
            custAccountSet.add(custTable.AccountNum);
        }

        inventItemSet.add(priceChangeTrackingOrig.ItemId);

        this.processSets(custAccountSet, inventItemSet);
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>    
    /// <param name = "_custAccountSet">Customer Accounts</param>
    /// <param name = "_inventItemSet">Items</param>
    public void processSets(Set _custAccountSet, Set _inventItemSet)
    {
        SetEnumerator       custAccountEnumerator, inventItemEnumerator;
        AccountNum          custAccount;
        ItemId              inventItem;
        boolean             validityCheck;
        METPriceChangeTracking priceChangeTrackingUpdate;

        inventItemEnumerator = _inventItemSet.getEnumerator();

        while(inventItemEnumerator.moveNext())
        {
            validityCheck = true;

            inventItem  = inventItemEnumerator.current();

            //1. Execute the Item/Site validity check
            validityCheck = this.ItemSiteValidation(inventItem, priceChangeTrackingOrig.InventSiteId);

            if(validityCheck)
            {
                custAccountEnumerator = _custAccountSet.getEnumerator();
                
                while(custAccountEnumerator.moveNext())
                {
                    custAccount = custAccountEnumerator.current();

                    //2. Execute the Customer/Item validity check
                    validityCheck = this.CustomerItemValidation(custAccount, inventItem);

                    if(validityCheck)
                    {
                        //update values for processing, but dont committ to DB 
                        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);
                        priceChangeTrackingUpdate.PriceDiscAccountRelation = custAccount;
                        priceChangeTrackingUpdate.ItemId                   = inventItem;
                        
                        this.createPriceDataFeedAll(priceChangeTrackingUpdate, priceChangeTrackingUpdate.PriceDiscLineNum, METConstants::emptyString);

                    }
                }
            }
        }
    }

/// <summary>
/// Get the Id of the record that caused the change
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <returns>Id of the record</returns>
public METChangeCode getChangeCode(METPriceChangeTracking _priceChangeTracking)
{
    return _priceChangeTracking.PriceDiscJournalNum;
}

/// <summary>
/// Get the type of the record that caused the change
/// </summary>
/// <returns>Type of the record</returns>
public METCreationType getOriginalCreationType()
{
    return METCreationType::Original;
}

/// <summary>
/// Get the type of the related record
/// </summary>
/// <returns>Related type</returns>
public METCreationType getRelatedCreationType()
{
    return METCreationType::RelatedTradeAgreement;
}

    /// <summary>
    /// Created the Related records
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change track record</param>
    /// <param name = "_lineNumberOrig">Line number of original record</param>
    public void createRelatedComponents(METPriceChangeTracking _priceChangeTracking, LineNumber _lineNumberOrig)
    {
        //Discount
        this.createRelatedPriceAdj(_priceChangeTracking, _lineNumberOrig, [RetailDiscountOfferTypeBase::Multibuy, RetailDiscountOfferTypeBase::DiscountOffer]);

        //Autocharge
        this.createRelatedAutoCharge(_priceChangeTracking, _lineNumberOrig);
    }
